/*
 * Apple Music project: charts and copy for the case-study page and the
 * homepage card, all from window.MUSIC_DATA (music-data.js, generated by
 * tools/build_music_data.py from analysis.sql). No number is typed by hand.
 */
(() => {
  "use strict";

  const D = window.MUSIC_DATA;
  if (!D) return;
  const Q = (name) => D.queries[name];
  const rows = (name) => Q(name).rows.map((r) => Object.fromEntries(Q(name).columns.map((c, i) => [c, r[i]])));
  const NS = "http://www.w3.org/2000/svg";
  const n = (v) => Number(v).toLocaleString("en-US");
  const pct = (v) => `${Number(v).toFixed(Number.isInteger(v) ? 0 : 1)}%`;

  function h(tag, attrs, ...kids) {
    const el = document.createElement(tag);
    for (const k in attrs || {}) if (attrs[k] != null) k === "class" ? (el.className = attrs[k]) : el.setAttribute(k, attrs[k]);
    kids.flat(Infinity).forEach((kid) => kid != null && el.append(kid));
    return el;
  }
  function s(tag, attrs, parent) {
    const el = document.createElementNS(NS, tag);
    for (const k in attrs) if (attrs[k] != null) el.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(el);
    return el;
  }
  function svg(w, hgt, label) {
    return s("svg", { class: "viz-svg", viewBox: `0 0 ${w} ${hgt}`, role: "img", "aria-label": label, focusable: "false" });
  }
  function text(el, x, y, str, attrs = {}) {
    const t = s("text", { x, y, ...attrs }, el);
    t.textContent = str;
    return t;
  }

  /* ----- The numbers, in words ----- */

  const o = rows("overview")[0];
  const mix = rows("genre_mix");
  const country = mix.find((r) => r.genre_family === "Country");
  const hiphop = mix.find((r) => r.genre_family === "Hip-Hop/Rap");
  const artists = rows("top_artists");
  const conc = rows("concentration")[0];
  const songs = rows("top_songs");
  const growth = rows("growth");
  const never = rows("never_played");
  const skips = rows("skips");
  const decades = rows("decades");
  const before2020 = growth.filter((r) => r.year < 2020).reduce((a, r) => a + r.songs_added, 0);
  const y2020 = growth.find((r) => r.year === 2020);
  const recent = never.filter((r) => r.year_added >= "2021").map((r) => r.pct_never_played);
  const most = skips.filter((r) => r.list === "most skipped");
  const least = skips.filter((r) => r.list === "least skipped");
  const newer = decades.filter((r) => r.decade >= 2010).reduce((a, r) => a + r.plays, 0);
  const allPlays = decades.reduce((a, r) => a + r.plays, 0);

  const FINDINGS = {
    genre_mix: `Country is ${pct(country.pct_of_library)} of my library but ${pct(country.pct_of_plays)} of everything I play. Hip-Hop/Rap is the reverse: the biggest share of the library (${pct(hiphop.pct_of_library)}), and ${pct(hiphop.pct_of_plays)} of plays.`,
    top_artists: `${artists[0].artist} and ${artists[1].artist} alone are ${pct(Math.round((artists[0].pct_of_plays + artists[1].pct_of_plays) * 10) / 10)} of my plays. My top 10 artists are ${pct(conc.top_10_share)}, out of ${n(conc.artists_played)} artists I’ve played at least once.`,
    top_songs: `“${songs[0].name}” by ${songs[0].artist} leads with ${n(songs[0].plays)} plays, ${n(songs[0].plays - songs[1].plays)} ahead of the next song.`,
    growth: `The library barely moved for over a decade (${n(before2020)} songs added before 2020), then took off: ${n(y2020.songs_added)} songs in 2020 alone.`,
    never_played: `${pct(o.pct_never_played)} of the library has never been played. It isn’t only old saves: since 2021, between ${pct(Math.min(...recent))} and ${pct(Math.max(...recent))} of each year’s additions are still waiting.`,
    skips: `${most[0].artist} gets skipped ${pct(most[0].skip_rate)} of the time; ${least[0].artist}, ${pct(least[0].skip_rate)}. Only artists with at least 150 plays and skips count here.`,
    decades: `Songs released in the 2010s and 2020s make up ${pct(Math.round((1000 * newer) / allPlays) / 10)} of my plays.`
  };

  /* ----- Charts ----- */

  // Two bars per genre family: share of the library vs share of plays.
  function pairedBars(list, { width = 560, labelW = 150, compact = false } = {}) {
    const row = compact ? 34 : 40, top = 26, max = Math.max(...list.flatMap((r) => [r.pct_of_library, r.pct_of_plays]));
    const span = width - labelW - 56;
    const el = svg(width, top + list.length * row, "Share of library vs share of plays by genre: " + list.map((r) => `${r.genre_family} ${r.pct_of_library}% of library, ${r.pct_of_plays}% of plays`).join("; "));
    s("rect", { class: "viz-bar viz-bar--base", x: labelW + 0.5, y: 4.5, width: 9, height: 9, rx: 2 }, el);
    text(el, labelW + 16, 13, "Share of library");
    s("rect", { class: "viz-bar viz-bar--hi", x: labelW + 130, y: 4, width: 10, height: 10, rx: 2 }, el);
    text(el, labelW + 146, 13, "Share of plays");
    list.forEach((r, i) => {
      const y = top + i * row;
      text(el, 0, y + 15, r.genre_family, { class: "viz-label" });
      const w1 = (r.pct_of_library / max) * span, w2 = (r.pct_of_plays / max) * span;
      s("rect", { class: "viz-bar viz-bar--base", x: labelW + 0.5, y: y + 2.5, width: Math.max(2, w1 - 1), height: 9, rx: 2 }, el);
      text(el, labelW + w1 + 6, y + 11, pct(r.pct_of_library), { class: "viz-small" });
      s("rect", { class: "viz-bar viz-bar--hi", x: labelW, y: y + 15, width: Math.max(2, w2), height: 10, rx: 2 }, el);
      text(el, labelW + w2 + 6, y + 24, pct(r.pct_of_plays), { class: "viz-value" });
    });
    return el;
  }

  function hbars(list, key, labelKey, fmt, { width = 560, labelW = 170, hi = 0, max = Math.max(...list.map((r) => r[key])) } = {}) {
    const row = 28, span = width - labelW - 70;
    const el = svg(width, list.length * row, list.map((r) => `${r[labelKey]} ${fmt(r[key])}`).join(", "));
    list.forEach((r, i) => {
      const y = i * row, w = Math.max(2, (r[key] / max) * span);
      text(el, 0, y + 15, r[labelKey], { class: "viz-label" });
      s("rect", { class: "viz-bar" + (i < hi ? " viz-bar--hi" : ""), x: labelW, y: y + 4, width: w, height: 14, rx: 2 }, el);
      text(el, labelW + w + 6, y + 15, fmt(r[key]), { class: "viz-value" });
    });
    return el;
  }

  function columns(list, key, labelKey, { width = 560, height = 200, hiWhen = () => false, labelEvery = 1, fmt = n, showValues = false } = {}) {
    const base = height - 22, top = showValues ? 18 : 8, max = Math.max(...list.map((r) => r[key]));
    const slot = width / list.length, bw = Math.min(34, slot * 0.66);
    const el = svg(width, height, list.map((r) => `${r[labelKey]}: ${fmt(r[key])}`).join(", "));
    s("line", { class: "viz-grid", x1: 0, x2: width, y1: base, y2: base }, el);
    list.forEach((r, i) => {
      const cx = slot * (i + 0.5), bh = r[key] ? Math.max(2, (r[key] / max) * (base - top)) : 0;
      const hi = hiWhen(r);
      if (bh) s("rect", { class: "viz-bar" + (hi ? " viz-bar--hi" : ""), x: cx - bw / 2, y: base - bh, width: bw, height: bh, rx: 2 }, el);
      if (showValues || hi) text(el, cx, base - bh - 6, fmt(r[key]), { class: "viz-value", "text-anchor": "middle" });
      if (i % labelEvery === 0 || hi || i === list.length - 1) text(el, cx, height - 4, String(r[labelKey]).replace(/^(\d{4})$/, "$1"), { "text-anchor": "middle", class: hi ? "viz-value" : null });
    });
    return el;
  }

  function figure(chart, caption) {
    return h("figure", { class: "viz mp-figure" }, chart, caption ? h("figcaption", {}, caption) : null);
  }

  /* ----- Case-study page ----- */

  function page() {
    const stats = document.querySelector("[data-stats]");
    if (!stats) return;
    [["Songs", n(o.songs)], ["Plays", n(o.plays)], ["Hours, if every play ran in full", "≈" + n(o.hours_if_played_in_full)], ["Never played", pct(o.pct_never_played)]]
      .forEach(([k, v]) => stats.append(h("div", {}, h("dt", {}, k), h("dd", {}, v))));

    const charts = {
      genre_mix: () => figure(pairedBars(mix), "Genre families, ordered by plays. Grouped from Apple’s 100+ labels by the clean step below."),
      top_artists: () => figure(hbars(artists, "plays", "artist", n, { hi: 2 }), "Plays per artist, all time."),
      top_songs: () => h("ol", { class: "mp-songs" }, songs.map((r) => h("li", {}, h("span", { class: "mp-songs__name" }, r.name), h("span", { class: "mp-songs__artist" }, r.artist), h("span", { class: "mp-songs__plays" }, n(r.plays) + " plays")))),
      growth: () => figure(columns(growth, "songs_added", "year", { hiWhen: (r) => r.year === 2020, labelEvery: 5 }), "Songs added per year, 2007–2026."),
      never_played: () => figure(columns(never, "pct_never_played", "year_added", { fmt: pct, showValues: true, hiWhen: () => false, height: 180 }), "Share of each year’s additions with no plays yet."),
      skips: () => {
        const max = Math.max(...skips.map((r) => r.skip_rate));   // one scale for both lists
        return h("div", { class: "mp-skips" },
          figure(hbars(most, "skip_rate", "artist", pct, { hi: 1, max }), "Most skipped: share of plays and skips that were skips."),
          figure(hbars(least, "skip_rate", "artist", pct, { max }), "Least skipped, on the same scale."));
      },
      decades: () => figure(columns(decades.map((r) => ({ ...r, label: r.decade + "s" })), "plays", "label", { hiWhen: (r) => r.decade >= 2010, fmt: n, labelEvery: 1, height: 180 }), "Plays by the decade a song was released.")
    };

    document.querySelectorAll("[data-q]").forEach((sec) => {
      const name = sec.dataset.q;
      const finding = sec.querySelector("[data-finding]");
      if (finding && FINDINGS[name]) finding.textContent = FINDINGS[name];
      const slot = sec.querySelector("[data-chart]");
      if (slot && charts[name]) slot.replaceChildren(charts[name]());
      sec.querySelectorAll("[data-sql]").forEach((code) => { code.textContent = Q(code.dataset.sql || name).sql; });
    });
    const clean = document.querySelector("[data-sql='clean']");
    if (clean) clean.textContent = Q("clean").sql;
    document.querySelectorAll("[data-exported]").forEach((el) => { el.textContent = new Date(D.exported + "T12:00:00Z").toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }); });

    // Listen along: one Apple Music player, four Replay playlists.
    const player = document.querySelector("[data-player]");
    if (player) {
      const frame = player.querySelector("iframe");
      player.querySelectorAll("[data-src]").forEach((btn) => btn.addEventListener("click", () => {
        player.querySelectorAll("[data-src]").forEach((b) => b.setAttribute("aria-pressed", String(b === btn)));
        frame.src = btn.dataset.src;
        frame.title = "Apple Music: " + btn.textContent;
      }));
    }
  }

  /* ----- Homepage card ----- */

  function card() {
    const el = document.querySelector("[data-music-card]");
    if (!el) return;
    el.querySelector("[data-music-desc]").textContent =
      `${n(o.songs)} songs saved since ${o.first_year}, loaded into SQLite and queried. Country is ${pct(country.pct_of_library)} of my library and ${pct(country.pct_of_plays)} of what I play.`;
    const stats = el.querySelector("[data-music-stats]");
    [["Top artist", artists[0].artist], ["On repeat", `“${songs[0].name}”, ${n(songs[0].plays)} plays`], ["Never played", `${pct(o.pct_never_played)} of the library`]]
      .forEach(([k, v]) => stats.append(h("div", {}, h("dt", {}, k), h("dd", {}, v))));
    el.querySelector("[data-music-chart]").replaceChildren(pairedBars(mix.slice(0, 4), { width: 460, labelW: 112, compact: true }));
  }

  page();
  card();
})();
